package es.vargontoc.storyteller.application.service;
import java.util.Objects; import java.util.Optional;
import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import es.vargontoc.storyteller.application.ports.in.character.CharacterReviewUseCase; import es.vargontoc.storyteller.application.ports.out.external.CharacterAgent; import es.vargontoc.storyteller.application.ports.out.external.CharacterImageConditionPort; import es.vargontoc.storyteller.domain.command.CatalogCharacterReviewCommand; import es.vargontoc.storyteller.domain.enums.RevisionStatus; import es.vargontoc.storyteller.domain.model.ActorMetadata; import es.vargontoc.storyteller.domain.request.CatalogCharacterReviewAgentRequest; import es.vargontoc.storyteller.domain.response.CatalogCharacterReviewAgentResult; import es.vargontoc.storyteller.domain.response.CatalogCharacterReviewRequestResult; import es.vargontoc.storyteller.domain.response.CatalogCharacterReviewView; import es.vargontoc.storyteller.infrastructure.persistence.*; import es.vargontoc.storyteller.shared.exceptions.AppException;
@Service public class CharacterReviewService implements CharacterReviewUseCase {
 private final CharacterAgent agent; private final CatalogCharacterJpaRepository characters; private final CatalogCharacterReviewJpaRepository reviews; private final Optional<CharacterImageConditionPort> images;
 public CharacterReviewService(CharacterAgent agent,CatalogCharacterJpaRepository characters,CatalogCharacterReviewJpaRepository reviews,Optional<CharacterImageConditionPort> images){this.agent=agent;this.characters=characters;this.reviews=reviews;this.images=images;}
 @Transactional public CatalogCharacterReviewRequestResult request(CatalogCharacterReviewCommand c){
  validate(c); var character=characters.findByIdForUpdate(c.catalogCharacterId()).orElseThrow(()->new AppException("Catálogo no encontrado",HttpStatus.NOT_FOUND)); var previous=reviews.findByCatalogCharacterIdAndStatus(c.catalogCharacterId(),RevisionStatus.PENDING);
  if(previous.isPresent()&&!c.replacePending())return CatalogCharacterReviewRequestResult.confirmationRequired();
  previous.ifPresent(p->{p.setStatus(RevisionStatus.DISCARDED);reviews.saveAndFlush(p);});
  var m=character.getMetadata(); var result=agent.review(new CatalogCharacterReviewAgentRequest(character.getName(),character.getNarrativeDescription(),character.getVisualDescription(),m.translate(),m.attributes(),c.target(),c.hint()));
  if(!result.accepted())return CatalogCharacterReviewRequestResult.proposal(result,false); requireComplete(result);
  boolean visualChanged=c.target().affectsVisualDescription()&&!Objects.equals(character.getVisualDescription(),result.visualDescription());
  boolean warning=visualChanged&&images.orElseThrow(()->new AppException("La condición de imágenes no está disponible",HttpStatus.SERVICE_UNAVAILABLE)).hasGeneratedImages(c.catalogCharacterId());
  var entity=new CatalogCharacterReviewJpaEntity(); entity.setCatalogCharacter(character);entity.setStatus(RevisionStatus.PENDING);entity.setTarget(c.target());entity.setHint(c.hint());entity.setCandidateName(result.name());entity.setCandidateNarrative(result.narrativeDescription());entity.setCandidateVisual(result.visualDescription());entity.setMetadata(new ActorMetadata(result.visualDescriptionEn(),result.visualAttributes()));reviews.save(entity); return CatalogCharacterReviewRequestResult.proposal(result,warning);
 }
 @Transactional(readOnly=true) public CatalogCharacterReviewView getPending(Long id){var r=reviews.findByCatalogCharacterIdAndStatus(id,RevisionStatus.PENDING).orElseThrow(()->new AppException("No existe revisión pendiente",HttpStatus.NOT_FOUND));return new CatalogCharacterReviewView(r.getId(),r.getTarget(),r.getHint(),r.getCandidateName(),r.getCandidateNarrative(),r.getCandidateVisual());}
 private void validate(CatalogCharacterReviewCommand c){if(c==null||c.catalogCharacterId()==null||c.target()==null||c.hint()==null||c.hint().isBlank())throw new AppException("La solicitud de revisión es inválida",HttpStatus.BAD_REQUEST);}
 private void requireComplete(CatalogCharacterReviewAgentResult r){if(blank(r.name())||blank(r.narrativeDescription())||blank(r.visualDescription()))throw new AppException("El agente devolvió una propuesta de revisión incompleta",HttpStatus.BAD_REQUEST);}
 @Transactional public CatalogCharacterReviewView resolve(es.vargontoc.storyteller.domain.command.CatalogCharacterReviewResolutionCommand command){
  if(command==null||command.catalogCharacterId()==null||command.reviewId()==null||(command.status()!=RevisionStatus.CONFIRMED&&command.status()!=RevisionStatus.DISCARDED))throw new AppException("Resolución inválida",HttpStatus.BAD_REQUEST);
  var character=characters.findByIdForUpdate(command.catalogCharacterId()).orElseThrow(()->new AppException("Catálogo no encontrado",HttpStatus.NOT_FOUND));
  var review=reviews.findByIdAndStatus(command.reviewId(),RevisionStatus.PENDING).orElseThrow(()->new AppException("No existe revisión pendiente",HttpStatus.NOT_FOUND));
  if(!command.catalogCharacterId().equals(review.getCatalogCharacter().getId()))throw new AppException("La revisión no pertenece al catálogo",HttpStatus.NOT_FOUND);
  if(command.status()==RevisionStatus.CONFIRMED){switch(review.getTarget()){case NARRATIVE->character.setNarrativeDescription(review.getCandidateNarrative());case VISUAL->{character.setVisualDescription(review.getCandidateVisual());character.setMetadata(review.getMetadata());}case BOTH->{character.setNarrativeDescription(review.getCandidateNarrative());character.setVisualDescription(review.getCandidateVisual());character.setMetadata(review.getMetadata());}}characters.save(character);}
  review.setStatus(command.status());reviews.save(review);return new CatalogCharacterReviewView(review.getId(),review.getTarget(),review.getHint(),review.getCandidateName(),review.getCandidateNarrative(),review.getCandidateVisual());
 }
 private boolean blank(String v){return v==null||v.isBlank();}
}
